import datetime

input_data = items[0].json

solutions = input_data.get('solution', {})
summary = input_data.get('summary', {})

lista_agendamentos = []
def agendamentos(solutions):

  relatorio_id = datetime.datetime.now().strftime("%Y%m%d_%H%M")

  for solution in solutions:
    for j in solution:
      texto_processado = f"REGISTO DE AGENDAMENTO:|Data {j[0].get('data', '')}|Turno {j[0].get('tipo', '')}|Duração {j[0].get('duracao', '')}segundos|Ids Cirurgias {j[1:]}"

      lista_agendamentos.append({
          "json": {
              "content": texto_processado,
              "data_agendamento": relatorio_id
          }
      })

  return lista_agendamentos

return agendamentos(solutions)

